export const zCatalogRuleValidatorRequest = z.object({
  data: z
    .object({
      match_type: z
        .enum(["filter", "similarity", "conflict", "resolve_for_shopper"])
        .register(z.globalRegistry, {
          description:
            'The type of matching operation to perform on catalog rules:\n\n- **filter**: Advanced rule filtering with AND logic. Returns rules that match ALL specified criteria.\n\n- **similarity**: Finds rules similar to the supplied rule using OR logic. Returns rules sorted by similarity score (highest first) with metadata indicating:\n  - Similarity score based on matching criteria (name: 100pts, account/customer/channel/tags: 5pts each, catalog: 3pts, pricebooks: 2pts, schedules: 2pts)  \n  - Whether the rule is active at the supplied match_date\n  - Whether the rule would be resolved for a shopper context\n\n- **conflict**: Checks for conflicts between the supplied rule and existing rules. Returns rules that would conflict if the new rule were created.\n\n- **resolve_for_shopper**: Determines the exact catalog rule that would be applied for a given shopper context. Returns the single most specific matching rule or defaults to "Default Catalog Resolution".\n',
        }),
      channels: z.array(z.string()).nullish(),
      tags: z.array(z.string()).nullish(),
      account_ids: z.array(z.string()).nullish(),
      account_tag_ids: z.array(z.string()).nullish(),
      customer_ids: z.array(z.string()).nullish(),
      pricebook_ids: z.array(z.string()).nullish(),
      schedules: z
        .array(
          z.object({
            valid_from: z.iso.datetime().optional(),
            valid_to: z.iso.datetime().optional(),
          }),
        )
        .nullish(),
      name: z.string().nullish(),
      catalog_id: z.string().nullish(),
      search_profile_slug: z.string().nullish(),
      match_date: z.iso.datetime().nullish(),
    })
    .optional(),
})

